INSERT INTO `app_notices` VALUES (1,'রমাদান স্পেশাল কুইজ','রমাদান উপলক্ষে বিশেষ নলেজ ব্যাটেল শুরু হয়েছে। অংশ নিন ও পয়েন্ট অর্জন করুন!','EVENT',NULL,1,'2026-09-22 22:05:50'),(2,'রক্তদান ক্যাম্পেইন','জরুরি প্রয়োজনে দীন ওয়ান ইসলামিক রক্তদান নেটওয়ার্কের মাধ্যমে মানুষের পাশে দাঁড়ান।','INFO',NULL,1,'2026-09-22 22:05:50');
