--
-- Table structure for table `gallery_images`
--

DROP TABLE IF EXISTS `gallery_images`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `gallery_images` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `image_uid` varchar(60) NOT NULL,
  `title` varchar(255) NOT NULL,
  `category` varchar(100) DEFAULT 'অন্যান্য',
  `file_url` varchar(500) NOT NULL,
  `file_path` varchar(500) NOT NULL,
  `width` int(10) unsigned DEFAULT 0,
  `height` int(10) unsigned DEFAULT 0,
  `original_size` bigint(20) unsigned DEFAULT 0,
  `compressed_size` bigint(20) unsigned DEFAULT 0,
  `saved_percent` decimal(5,2) DEFAULT 0.00,
  `mime_type` varchar(50) DEFAULT 'image/webp',
  `original_name` varchar(255) DEFAULT '',
  `file_name` varchar(255) DEFAULT '',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `image_uid` (`image_uid`),
  KEY `idx_gallery_cat` (`category`),
  KEY `idx_gallery_created` (`created_at`)
) ENGINE=InnoDB AUTO_INCREMENT=34 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

