--
-- Table structure for table `hadith_books`
--

DROP TABLE IF EXISTS `hadith_books`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `hadith_books` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `book_slug` varchar(60) NOT NULL,
  `name_bn` varchar(150) NOT NULL,
  `author_bn` varchar(120) DEFAULT NULL,
  `author_en` varchar(120) DEFAULT NULL,
  `initials` varchar(20) DEFAULT 'H',
  `color_hex` varchar(20) DEFAULT '#10B981',
  `name_en` varchar(150) DEFAULT NULL,
  `name_ar` varchar(150) DEFAULT NULL,
  `total_hadith` int(10) unsigned DEFAULT 0,
  `total_hadith_bn` varchar(50) DEFAULT '',
  `description_bn` text DEFAULT NULL,
  `display_order` int(10) unsigned DEFAULT 0,
  `is_active` tinyint(1) DEFAULT 1,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `book_slug` (`book_slug`)
) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

