INSERT INTO `hadith_books` VALUES 
(1,'bukhari','সহীহ বুখারী','ইমাম বুখারি','Imam Bukhari','B','#22C55E','Sahih al-Bukhari','صحيح البخاري',7563,'৭৫৬৩টি হাদিস','ইমাম বুখারী (রহ.) সংকলিত সর্বাধিক বিশুদ্ধ হাদীস গ্রন্থ।',1,1,'2026-09-28 20:20:27','2026-09-28 20:20:27'),
(2,'muslim','সহীহ মুসলিম','ইমাম মুসলিম','Imam Muslim','M','#0284C7','Sahih Muslim','صحيح مسلم',7500,'৭৫০০টি হাদিস','ইমাম মুসলিম (রহ.) সংকলিত অন্যতম বিশুদ্ধ হাদীস গ্রন্থ।',2,1,'2026-09-28 20:20:27','2026-09-28 20:20:27'),
(3,'nasai','সুনানে আন-নাসায়ী','ইমাম নাসায়ী','Imam Nasa\'i','N','#0EA5E9','Sunan an-Nasa\'i','سنن النسائي',5758,'৫৭৫৮টি হাদিস','ইমাম আহমদ আন-নাসায়ী (রহ.) সংকলিত হাদীস গ্রন্থ।',3,1,'2026-09-28 20:20:27','2026-09-28 20:20:27'),
(4,'abu_dawood','সুনানে আবু দাউদ','ইমাম আবু দাউদ','Imam Abu Dawood','AD','#9333EA','Sunan Abi Dawud','سنن أبي داود',5274,'৫২৭৪টি হাদিস','ইমাম আবু দাউদ (রহ.) সংকলিত ফিকহি হাদীস গ্রন্থ।',4,1,'2026-09-28 20:20:27','2026-09-28 20:20:27'),
(5,'tirmidhi','জামে\' আত-তিরমিযী','ইমাম তিরমিজি','Imam Tirmidhi','T','#3B82F6','Jami\' at-Tirmidhi','جامع الترمذي',3956,'৩৯৫৬টি হাদিস','ইমাম আত-তিরমিযী (রহ.) সংকলিত হাদিসের মান ও ফিকহ গ্রন্থ।',5,1,'2026-09-28 20:20:27','2026-09-28 20:20:27'),
(6,'ibn_majah','সুনানে ইবনে মাজাহ','ইমাম ইবনে মাজাহ','Imam Ibn Majah','IM','#F97316','Sunan Ibn Majah','سنن ابن ماجه',4341,'৪৩৪১টি হাদিস','ইমাম ইবনে মাজাহ (রহ.) সংকলিত সিহাহ সিত্তাহর অন্যতম গ্রন্থ।',6,1,'2026-09-28 20:20:27','2026-09-28 20:20:27'),
(7,'muwatta_malik','মুয়াত্তা ইমাম মালিক','ইমাম মালিক','Imam Malik','MI','#38BDF8','Muwatta Imam Malik','موطأ الإمام مالك',1850,'১৮৫০টি হাদিস','ইমাম মালিক ইবনে আনাস (রহ.) সংকলিত প্রাচীনতম হাদীস ও ফিকহ গ্রন্থ।',7,1,'2026-09-28 20:20:27','2026-09-28 20:20:27'),
(8,'riyadus_salihin','রিয়াদুস সালেহীন','ইমাম নববী','Imam Nawawi','RS','#EC4899','Riyadus Salihin','رياض الصالحين',1896,'১৮৯৬টি হাদিস','ইমাম মুহিউদ্দীন ইয়াহইয়া আন-নববী (রহ.) সংকলিত নেক আমলের হাদীস সম্ভার।',8,1,'2026-09-28 20:20:27','2026-09-28 20:20:27'),
