--
-- Table structure for table `hadith_chapters`
--

DROP TABLE IF EXISTS `hadith_chapters`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `hadith_chapters` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `book_slug` varchar(50) NOT NULL DEFAULT 'bukhari',
  `chapter_number` int(11) NOT NULL,
  `chapter_number_bn` varchar(50) DEFAULT '',
  `title_bn` varchar(255) NOT NULL,
  `title_en` varchar(255) DEFAULT '',
  `hadith_range` varchar(100) DEFAULT '',
  `hadith_range_bn` varchar(100) DEFAULT '',
  `start_hadith` int(11) DEFAULT 0,
  `end_hadith` int(11) DEFAULT 0,
  `total_hadith` int(11) DEFAULT 0,
  `display_order` int(11) DEFAULT 0,
  `is_active` tinyint(1) DEFAULT 1,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uniq_book_chapter` (`book_slug`,`chapter_number`),
  KEY `idx_book_slug` (`book_slug`)
) ENGINE=InnoDB AUTO_INCREMENT=42 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

