--
-- Table structure for table `hadith_items`
--

DROP TABLE IF EXISTS `hadith_items`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `hadith_items` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `book_slug` varchar(60) NOT NULL,
  `chapter_number` int(10) unsigned DEFAULT 1,
  `hadith_number` int(10) unsigned NOT NULL,
  `hadith_number_bn` varchar(50) DEFAULT '',
  `narrator_bn` varchar(120) DEFAULT NULL,
  `narrator_en` varchar(255) DEFAULT '',
  `arabic_text` mediumtext NOT NULL,
  `bangla_text` mediumtext NOT NULL,
  `english_text` mediumtext DEFAULT NULL,
  `grade` varchar(40) DEFAULT 'সহীহ (Sahih)',
  `reference` varchar(255) DEFAULT NULL,
  `footnote_bn` text DEFAULT NULL,
  `footnote_en` text DEFAULT NULL,
  `words_json` longtext DEFAULT NULL,
  `is_active` tinyint(1) DEFAULT 1,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uniq_book_hadith` (`book_slug`,`hadith_number`),
  KEY `idx_book_num` (`book_slug`,`hadith_number`),
  KEY `idx_book_chap_num` (`book_slug`,`chapter_number`,`hadith_number`),
  KEY `idx_active` (`is_active`)
) ENGINE=InnoDB AUTO_INCREMENT=8 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

