DROP TABLE IF EXISTS `hadith_scraped_staging`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `hadith_scraped_staging` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `source_url` varchar(500) DEFAULT NULL,
  `book_slug` varchar(60) NOT NULL,
  `chapter_number` int(10) unsigned DEFAULT 1,
  `chapter_title_bn` varchar(255) DEFAULT '',
  `chapter_title_en` varchar(255) DEFAULT '',
  `hadith_number` int(10) unsigned NOT NULL,
  `hadith_number_bn` varchar(50) DEFAULT '',
  `narrator_bn` varchar(255) DEFAULT '',
  `narrator_en` varchar(255) DEFAULT '',
  `arabic_text` mediumtext NOT NULL,
  `bangla_text` mediumtext NOT NULL,
  `english_text` mediumtext DEFAULT NULL,
  `grade` varchar(60) DEFAULT 'সহীহ (Sahih)',
  `reference` varchar(255) DEFAULT NULL,
  `footnote_bn` text DEFAULT NULL,
  `footnote_en` text DEFAULT NULL,
  `status` enum('pending','approved','rejected') DEFAULT 'pending',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_staging_book_chap` (`book_slug`,`chapter_number`),
  KEY `idx_staging_status` (`status`),
  KEY `idx_staging_created` (`created_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
