INSERT INTO `push_notifications` VALUES (1,'নতুন আপডেট ভার্সন এসেছে!','দীন ওয়ান অ্যাপের নতুন ভার্সন রিলিজ হয়েছে। এখনই আপডেট করে নতুন ফিচার উপভোগ করুন।','APP_UPDATE','app_update',NULL,NULL,'CRITICAL','ALL','SENT',0,1,'Admin','2026-09-22 22:05:50'),(2,'ইসলামিক নলেজ ব্যাটেল শুরু হয়েছে!','আজকের কুইজ প্রতিযোগিতায় অংশ নিয়ে অন্যান্য মুসলিম ভাইদের সাথে জ্ঞান যাচাই করুন।','NEW_FEATURE','action_knowledge_battle',NULL,NULL,'HIGH','ALL','SENT',0,1,'Admin','2026-09-22 22:05:50');
/*!40000 ALTER TABLE `push_notifications` ENABLE KEYS */;
UNLOCK TABLES;

--
-- Table structure for table `quiz_categories`
--

DROP TABLE IF EXISTS `quiz_categories`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `quiz_categories` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `category_id` varchar(60) NOT NULL,
  `tag_bn` varchar(100) DEFAULT 'সাধারণ জ্ঞান',
  `tag_en` varchar(100) DEFAULT 'General Knowledge',
  `title_bn` varchar(100) NOT NULL,
  `title_en` varchar(100) DEFAULT NULL,
  `description_bn` varchar(255) DEFAULT NULL,
  `description_en` text DEFAULT NULL,
  `total_questions` int(10) unsigned DEFAULT 5,
  `duration_minutes` int(10) unsigned DEFAULT 10,
  `points_per_question` int(10) unsigned DEFAULT 10,
  `icon` varchar(60) DEFAULT 'ic_quiz_general',
  `display_order` int(10) unsigned DEFAULT 0,
  `is_active` tinyint(1) DEFAULT 1,
  PRIMARY KEY (`id`),
  UNIQUE KEY `category_id` (`category_id`)
) ENGINE=InnoDB AUTO_INCREMENT=44 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

