DROP TABLE IF EXISTS `quran_journey_lessons`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `quran_journey_lessons` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `day_number` int(10) unsigned NOT NULL DEFAULT 1,
  `level_name` varchar(50) NOT NULL DEFAULT 'primary',
  `surah_number` int(10) unsigned NOT NULL DEFAULT 1,
  `ayah_number` int(10) unsigned NOT NULL DEFAULT 2,
  `surah_name_bn` varchar(150) NOT NULL DEFAULT 'সূরা আল-ফাতিহা',
  `surah_name_en` varchar(150) NOT NULL DEFAULT 'Surah Al-Fatihah',
  `arabic_ayah` text NOT NULL,
  `meaning_bn` text NOT NULL,
  `meaning_en` text DEFAULT NULL,
  `audio_url` varchar(255) DEFAULT NULL,
  `words_json` text NOT NULL,
  `quiz_challenge` text NOT NULL,
  `correct_option` varchar(255) NOT NULL,
  `options_json` text NOT NULL,
  `lesson_bn` text NOT NULL,
  `lesson_en` text DEFAULT NULL,
  `amol_bn` text NOT NULL,
  `amol_en` text DEFAULT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_day` (`day_number`),
  KEY `idx_active` (`is_active`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

