/*!40000 ALTER TABLE `tasbih_challenges` DISABLE KEYS */;
INSERT INTO `tasbih_challenges` VALUES (1,0,'রব্বি ইন্নি লিমা আনযালতা ইলাইয়া মিন খাইরিন ফাকির','Rabbi inni lima anzalta ilayya min khayrin faqir','“হে আমার রব, নিশ্চয় আপনি আমার প্রতি যে অনুগ্রহই নাযিল করবেন, আমি তার মুখাপেক্ষী” — সূরা আল-ক্বাসাস: ২৪','“My Lord, indeed I am in need of whatever good You would send down to me” — Surah Al-Qasas: 24',100,50,1,'2026-09-26 15:30:10'),(2,1,'ইয়া মুক্বাল্লিবাল কুলূব, সাব্বিত ক্বালবি \'আলা দ্বীনিক','Ya Muqallib al-qulub, thabbit qalbi \'ala dinik','“হে অন্তরসমূহের পরিবর্তনকারী! আমার অন্তরকে আপনার দ্বীনের ওপর অবিচল রাখুন” — জামে তিরমিযী: ২১৪০','“O Controller of the hearts, make my heart steadfast upon Your religion” — Jami\' at-Tirmidhi: 2140',100,50,1,'2026-09-26 15:30:10'),(3,2,'লা ইলাহা ইল্লাল্লাহু মুহাম্মাদুর রাসুলুল্লাহ','La ilaha illallah, Muhammadur Rasulullah','“আল্লাহ ব্যতীত কোনো উপাস্য নেই, মুহাম্মদ (সা.) আল্লাহর রাসুল” — সহীহ বুখারী: ৮','“There is no deity except Allah, and Muhammad is the Messenger of Allah” — Sahih Bukhari: 8',100,50,1,'2026-09-26 15:30:10'),(4,3,'সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম','Sallallahu \'alayhi wa sallam','“আল্লাহ তাঁর ওপর শান্তি ও বরকত বর্ষণ করুন” — সহীহ মুসলিম: ৪০৮','“May Allah bless him and grant him peace” — Sahih Muslim: 408',100,50,1,'2026-09-26 15:30:10'),(5,4,'হাসবুনাল্লাহু ওয়া নি\'মাল ওয়াকিল','Hasbunallahu wa ni\'mal wakeel','“আল্লাহই আমাদের জন্য যথেষ্ট, তিনিই উত্তম অভিভাবক” — সূরা আলে-ইমরান: ১৭৩','“Allah is sufficient for us, and He is the best disposer of affairs” — Surah Ali \'Imran: 173',100,50,1,'2026-09-26 15:30:10'),(6,5,'সুবহানাল্লাহিল আযীম','SubhanAllahil Azeem','“মহিমান্বিত মহান আল্লাহ অতীব পবিত্র” — সহীহ বুখারী: ৬৪০৬','“Glory be to Allah, the Supreme” — Sahih Bukhari: 6406',100,50,1,'2026-09-26 15:30:10'),(7,6,'আল্লাহুম্মা সাল্লি আলা মুহাম্মাদ','Allahumma salli \'ala Muhammad','“হে আল্লাহ! আপনি মুহাম্মদ (সা.)-এর ওপর সালাত ও রহমত বর্ষণ করুন” — সহীহ বুখারী: ৩৩৭০','“O Allah, send blessings upon Muhammad” — Sahih Bukhari: 3370',100,50,1,'2026-09-26 15:30:10'),(8,7,'লা হাওলা ওয়া লা কুওয়াতা ইল্লা বিল্লাহ','La hawla wa la quwwata illa billah','“আল্লাহর সাহায্য ব্যতীত কোনো শক্তি নেই, কোনো পরাক্রম নেই” — সহীহ বুখারী: ৪২০৫','“There is no power and no strength except with Allah” — Sahih Bukhari: 4205',100,50,1,'2026-09-26 15:30:10'),(9,8,'সুবহানাল্লাহি ওয়া বিহামদিহি','SubhanAllahi wa bihamdihi','“আল্লাহর প্রশংসাসহ তাঁর পবিত্রতা ঘোষণা করছি” — সহীহ বুখারী: ৬৪০৫','“Glory be to Allah and His is the praise” — Sahih Bukhari: 6405',100,50,1,'2026-09-26 15:30:10'),(10,9,'লা ইলাহা ইল্লাল্লাহ','La ilaha illallah','“আল্লাহ ব্যতীত সত্য কোনো উপাস্য নেই” — সহীহ মুসলিম: ২৬','“There is no deity except Allah” — Sahih Muslim: 26',100,50,1,'2026-09-26 15:30:10'),(11,10,'আস্তাগফিরুল্লাহ','Astaghfirullah','“আমি আল্লাহর নিকট ক্ষমা প্রার্থনা করছি” — সহীহ মুসলিম: ৭০৩৪','“I seek forgiveness from Allah” — Sahih Muslim: 7034',100,50,1,'2026-09-26 15:30:10'),(12,11,'আল্লাহু আকবার','Allahu Akbar','“আল্লাহ মহান” — সহীহ বুখারী: ৮৪২','“Allah is the Greatest” — Sahih Bukhari: 842',100,50,1,'2026-09-26 15:30:10'),(13,12,'সুবহানাল্লাহ','SubhanAllah','“আল্লাহ অতীব পবিত্র” — সহীহ মুসলিম: ৫৯১','“Glory be to Allah” — Sahih Muslim: 591',100,50,1,'2026-09-26 15:30:10'),(14,13,'আলহামদুলিল্লাহ','Alhamdulillah','“সকল প্রশংসা আল্লাহর জন্য” — সহীহ মুসলিম: ২২৩','“All praise is due to Allah” — Sahih Muslim: 223',100,50,1,'2026-09-26 15:30:10');
/*!40000 ALTER TABLE `tasbih_challenges` ENABLE KEYS */;
UNLOCK TABLES;

